#!/usr/bin/env bash
# Strip the harness-added attribution footer from a cloud session's PR body (#261). A cloud session
# can end its PR body with `_Generated by [Claude Code](https://claude.ai/code/session_...)_` even
# when its brief says "No attribution lines": the harness adds it when the PR is created, so
# repeating the rule in the brief does not stop it. This removes that trailing line, the blank
# lines around it and a `---` (or `***`, `___`) rule left trailing above it, over REST
# (`PATCH pulls/N`), and reads the body back. A body edit does not change the head: no re-review.
#
# Usage: pr-footer.sh --pr N [--policy auto|strip|keep] [--brief FILE] [--pattern ERE] [--dry-run]
#                     [--repo OWNER/REPO]
#        pr-footer.sh --cloud [--head ERE] [--policy ...] [--brief FILE] [--pattern ERE] [--dry-run]
#                     [--repo OWNER/REPO]
#   --pr       one PR. --cloud: every open PR whose head branch matches --head (default
#              ^work/[0-9]+-auto$, the branch cloud sessions push), from one REST list read.
#   --policy   strip: always strip. keep: never (the repository wants the attribution; no GitHub
#              call is made). auto (the default, or ORCHESTRATE_PR_FOOTER_POLICY): strip only when
#              the brief the cloud sessions follow says "No attribution" (case-insensitive), else
#              keep. The brief is --brief FILE, else <state dir>/cloud-brief.md when present, else
#              roles/cloud-session-brief.md (which says it). Dispatching with --brief-ref, pass the
#              repository's own brief: --brief <checkout>/.claude/briefs/implement.md.
#   --pattern  the footer line, an awk ERE matched against each trailing line with its trailing
#              whitespace removed (default ORCHESTRATE_PR_FOOTER_PATTERN, else
#              ^_Generated (by|with) \[Claude Code\]\(.*\)_$). Only trailing lines are removed:
#              a match in the middle of the body is left alone.
#   --dry-run  print what would change; no write.
# Output, one line per PR: "clean #N" (no footer, no write) | "stripped #N" | "would strip #N" |
#   "strip failed #N (exit E)" | "unverified #N: ..." ; or one "skipped: policy keep (<why>)" line.
# Each strip is logged to <state dir>/hygiene-actions.log.
# Exit: 0 done (or nothing to do) | 2 usage | 5 a write failed or the footer is still there after
#       it | 7 a PR or the PR list could not be read | 9 a write was sent but not read back.
set -euo pipefail
# This script's directory with no subshell or dirname process: every script start pays for it (#112).
case "$0" in /*/*) here=${0%/*} ;; */*) here=$PWD/${0%/*} ;; *) here=$PWD ;; esac
# shellcheck source=_lib.sh
source "$here/_lib.sh"
orch_gh_priority low

repo="" pr="" cloud=no head_re='^work/[0-9]+-auto$' brief="" dry=no
policy=${ORCHESTRATE_PR_FOOTER_POLICY:-auto}
pattern=${ORCHESTRATE_PR_FOOTER_PATTERN:-'^_Generated (by|with) \[Claude Code\]\(.*\)_$'}
while (($#)); do
  case "$1" in
    --repo) repo=$2; shift 2 ;;
    --pr) pr=$2; shift 2 ;;
    --cloud) cloud=yes; shift ;;
    --head) head_re=$2; shift 2 ;;
    --policy) policy=$2; shift 2 ;;
    --brief) brief=$2; shift 2 ;;
    --pattern) pattern=$2; shift 2 ;;
    --dry-run) dry=yes; shift ;;
    -h | --help) orch_usage; exit 0 ;;
    *) echo "pr-footer.sh: unknown argument: $1" >&2; exit 2 ;;
  esac
done
{ [[ "$cloud" == yes && -z "$pr" ]] || [[ "$cloud" == no && "$pr" =~ ^[0-9]+$ ]]; } || { orch_usage >&2; exit 2; }
case "$policy" in auto | strip | keep) ;; *) echo "pr-footer.sh: --policy must be auto, strip or keep" >&2; exit 2 ;; esac
[[ -n "$pattern" ]] || { echo "pr-footer.sh: --pattern is empty" >&2; exit 2; }
repo=$(orch_repo "$repo")
state=$(orch_state_dir "$repo")

if [[ "$policy" == auto ]]; then
  if [[ -z "$brief" ]]; then
    brief="$here/../roles/cloud-session-brief.md"
    [[ ! -f "$state/cloud-brief.md" ]] || brief="$state/cloud-brief.md"
  fi
  [[ -f "$brief" ]] || { echo "skipped: policy keep (brief $brief not found)"; exit 0; }
  grep -qi 'no attribution' "$brief" || { echo "skipped: policy keep (brief $brief does not say No attribution)"; exit 0; }
elif [[ "$policy" == keep ]]; then
  echo "skipped: policy keep (--policy keep)"; exit 0
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
export PR_FOOTER_RE=$pattern

# strip_body IN OUT: write IN without its trailing footer to OUT; return 1 when IN has none.
strip_body() {
  awk '{ line[NR] = $0 }
    function trimmed(s) { sub(/[ \t\r]+$/, "", s); return s }
    function skip_blank() { while (n > 0 && line[n] ~ /^[ \t\r]*$/) n-- }
    END {
      n = NR; pat = ENVIRON["PR_FOOTER_RE"]; found = 0
      skip_blank()
      while (n > 0 && trimmed(line[n]) ~ pat) { found = 1; n--; skip_blank() }
      if (!found) exit 1
      if (n > 0 && trimmed(line[n]) ~ /^ *(---+|\*\*\*+|___+)$/) { n--; skip_blank() }
      for (i = 1; i <= n; i++) print line[i]
    }' "$1" >"$2"
}

read_body() { # PR OUT: the PR's body (empty when none) into OUT
  local json
  json=$(orch_read_retry 3 gh api "repos/$repo/pulls/$1") || return 1
  jq -r '.body // ""' <<<"$json" >"$2"
}

worst=0
note() { # exit code: 9 outranks 7 outranks 5
  case "$1" in 9) worst=9 ;; 7) ((worst == 9)) || worst=7 ;; 5) ((worst != 0)) || worst=5 ;; esac
}

one() { # PR BODYFILE
  local n=$1 in=$2 out="$work/new-$1" rc=0
  if ! strip_body "$in" "$out"; then echo "clean #$n"; return; fi
  if [[ "$dry" == yes ]]; then echo "would strip #$n"; return; fi
  jq -n --rawfile b "$out" '{body: ($b | rtrimstr("\n"))}' >"$work/patch-$n.json"
  gh api -X PATCH "repos/$repo/pulls/$n" --input "$work/patch-$n.json" >/dev/null 2>&1 || rc=$?
  if ! read_body "$n" "$work/after-$n"; then
    echo "unverified #$n: footer strip sent (exit $rc) but the body was not read back; rerun"; note 9; return
  fi
  if strip_body "$work/after-$n" /dev/null; then
    echo "strip failed #$n (exit $rc)"; note 5; return
  fi
  printf '%s\tpr-footer\tpr=%s\tstripped\n' "$(orch_iso "$(orch_now)")" "$n" >>"$state/hygiene-actions.log"
  echo "stripped #$n"
}

if [[ "$cloud" == no ]]; then
  read_body "$pr" "$work/body-$pr" || { echo "unverified #$pr: the PR could not be read"; exit 7; }
  one "$pr" "$work/body-$pr"
  exit "$worst"
fi

list=$(orch_read_retry 3 gh api --paginate "repos/$repo/pulls?state=open&per_page=100") ||
  { echo "unverified: the open PR list could not be read"; exit 7; }
nums=$(jq -rs --arg re "$head_re" 'add // [] | .[] | select(.head.ref | test($re)) | .number' <<<"$list") ||
  { echo "unverified: the open PR list did not parse"; exit 7; }
for n in $nums; do
  jq -rs --argjson n "$n" 'add | .[] | select(.number == $n) | .body // ""' <<<"$list" >"$work/body-$n"
  one "$n" "$work/body-$n"
done
exit "$worst"
